 const bad=config.vehicleHours.findIndex(h=>!Number.isFinite(h.start)||!Number.isFinite(h.end)||h.start>=h.end);if(bad>=0)return status(`Revisá inicio y fin de la camioneta ${bad+1}.`,true);
