function editBookContact(c=null){$('book').close();openEdit('depot');bookMode=true;current=null;selectedContact=c;selectedPlaceId=c?.placeId||null;$('stopScheduleFields').hidden=true;$('contactFields').hidden=false;$('contactName').value=c?.name||'';$('aliases').value=c?.aliases.join('\n')||'';$('editTitle').textContent=c?'Editar dirección':'Agregar dirección';$('editName').textContent='Guardada para reutilizar en próximas jornadas.';$('editAddress').value=c?.address||'';$('editCity').value=c?.city||'';$('mapsLink').value=c?.mapsUrl||'';updateGoogleSearch();$('lat').value=c?.coord?.[0]??'';$('lon').value=c?.coord?.[1]??'';$('confirmed').checked=!!c?.coord;$('contactName').focus();}
$('openBook').onclick=()=>{renderBook();$('book').showModal()};$('closeBook').onclick=()=>$('book').close();$('bookSearch').oninput=renderBook;$('addContact').onclick=()=>editBookContact();
$('bookRows').onclick=async e=>{const id=e.target.dataset.book;if(id){editBookContact(contacts.find(c=>c.id===id));return;}const remove=e.target.dataset.deleteContact;if(!remove)return;const c=contacts.find(c=>c.id===remove);if(!c||!confirm(`¿Eliminar de la agenda a ${c.name}, ${c.address}? Los movimientos de la jornada actual se conservan.`))return;
 const button=e.target;button.disabled=true;try{const res=await fetch('/api/contacts?id='+encodeURIComponent(remove),{method:'DELETE'});const data=await res.json();if(!res.ok)throw Error(data.error||'No se pudo eliminar.');contacts=contacts.filter(c=>c.id!==remove);for(const s of stops)if(s.contactId===remove)delete s.contactId;renderBook();$('bookStatus').textContent='Dirección eliminada de la agenda.';}catch(err){$('bookStatus').textContent=err.message;button.disabled=false;}};


