function syncExactTime(){const exact=$('exactTime').checked;$('editTo').disabled=exact;$('editFrom2').disabled=exact;$('editTo2').disabled=exact;if(exact){$('editTo').value=$('editFrom').value;$('editFrom2').value='';$('editTo2').value=''}$('rawSchedule').textContent=(current?`Horario del archivo: ${current.schedule||'sin especificar'}. `:'')+(exact?'La atención comienza a esta hora; el tiempo en el lugar se cuenta a continuación.':'La atención debe terminar dentro de la ventana horaria.')}
$('exactTime').onchange=syncExactTime;$('editFrom').onchange=syncExactTime;
$('useGoogleLink').onclick=async()=>{if(busy)return;selectedPlaceId=null;const raw=$('mapsLink').value.trim();let coord=null,url=null;const m=raw.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);if(m){coord=[+m[1],+m[2]];if(Math.abs(coord[0])>90||Math.abs(coord[1])>180)return $('mapsStatus').textContent='El enlace no identifica una dirección válida.';url=`https://www.google.com/maps/search/?api=1&query=${coord.join(',')}`}else{url=googleMapsURL(raw)?.href;if(!url)return $('mapsStatus').textContent='Pegá un enlace de Google Maps o escribí la dirección en el formulario.';coord=mapCoordinates(url)}if(!coord){lock(true);$('mapsStatus').textContent='Leyendo el enlace de Google Maps…';try{const response=await fetch('/api/maps-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url}),signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error);coord=data.coord;url=data.url}catch(e){$('mapsStatus').textContent=e.message;return}finally{lock(false)}}$('lat').value=coord[0];$('lon').value=coord[1];$('mapsLink').value=url;$('confirmed').checked=false;$('mapsStatus').textContent='Dirección vinculada a Google Maps. Guardá para recordarla en la agenda.';$('candidates').innerHTML='';};

