async function saveContact(body){const response=await fetch('/api/contacts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo guardar la dirección.');return data.contact}
async function persistStop(s,overrides={}){const data={address:s.address,city:s.city,windows:s.windows,service:s.service,contactId:s.contactId,priorDone:!!s.priorDone,...overrides};const response=await fetch('/api/daily-edits',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:$('planDate').value,key:s.key,data})});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo guardar la corrección de la jornada.');dailyEdits.set(s.key,data)}
async function resolveLocations(){let found=0,failed=0,saveErrors=0,error='';const pending=stops.filter(s=>s.address&&!s.coord);for(let i=0;i<pending.length;i++){const s=pending[i];status(`Ubicando ${i+1} de ${pending.length}: ${s.address}`);let matches;try{matches=await checkedLocation(s.address,s.city,s.placeId||'')}catch(e){s.locationError=e.message;if(e.locationMismatch){failed++;continue}error=e.message;break}s.candidates=matches;if(!matches.length){s.locationError='Google Maps no encontró esta dirección';failed++;continue}s.coord=[Number(matches[0].lat),Number(matches[0].lon)];s.placeId=matches[0].placeId;s.confirmed=true;s.locationError='';found++;try{const c=contacts.find(c=>c.id===s.contactId)||contacts.find(c=>c.aliases.some(a=>norm(a)===norm(s.name))&&norm(c.address)===norm(s.address)&&norm(c.city)===norm(s.city));const saved=await saveContact({id:c?.id,name:c?.name||s.name,aliases:c?.aliases||[s.name],address:s.address,city:s.city,coord:s.coord,confirmed:true,placeId:s.placeId});contacts=contacts.filter(c=>c.id!==saved.id);contacts.push(saved);s.contactId=saved.id;s.mapsUrl=saved.mapsUrl;await persistStop(s)}catch{saveErrors++}}return {found,failed,saveErrors,error}}
function drawReadiness(){const report=assessReadiness(stops);const visible=report.entries.filter(x=>autoAttempted||x.reasons.some(r=>r!=='Sin ubicar en Google Maps'));$('readinessPanel').hidden=!visible.length&&dayReady;$('readinessTitle').textContent=`${report.ready.length} movimientos listos · ${visible.length} con datos pendientes`;$('readinessItems').innerHTML=visible.map(({s,reasons})=>`<div class="pending-row"><span><strong>${esc(s.np)} · ${esc(s.name)}</strong><br>${esc(s.address||'Dirección faltante')}<br>${reasons.filter(r=>autoAttempted||r!=='Sin ubicar en Google Maps').map(esc).join(' · ')}</span><button class="edit-button" data-pending="${s.id}">Corregir</button></div>`).join('');$('reviewNext').hidden=!visible.length;}
$('readinessItems').onclick=e=>{if(!busy&&e.target.dataset.pending)openEdit(e.target.dataset.pending)};$('reviewNext').onclick=()=>{const entry=assessReadiness(stops).entries.find(x=>autoAttempted||x.reasons.some(r=>r!=='Sin ubicar en Google Maps'));if(entry)openEdit(entry.s.id)};$('reloadDay').onclick=()=>loadDay();

function roadSummary(roads){if(!roads||roads.error)return `<div class="notice warning"><strong>Medición de calles incompleta.</strong> ${esc(roads?.error||'Sin datos de Google.')} No se pudo usar esta medición para comparar alternativas. Volvé a calcular para reintentar.</div>`;return `<div class="notice"><h2>Calles compartidas · ${roads.pairKm.toFixed(2)} km acumulados por pareja</h2><p>${roads.outsideKm.toFixed(2)} km fuera del entorno de Campana · ${roads.depotKm.toFixed(2)} km dentro de los 300 m del depósito.</p><p>${roads.reviewWarning?`Revisión adicional incompleta: ${esc(roads.reviewWarning)} Se conserva el último plan medido.`:"La revisión prueba conjuntos de NPs e intercambios entre camionetas. La búsqueda es limitada: las coincidencias restantes no se consideran inevitables."}</p><p>Se compararon ${roads.alternatives} alternativas distintas. Coincidencias fuera de Campana: ${roads.initialOutsideKm.toFixed(2)} → ${roads.outsideKm.toFixed(2)} km. Se priorizan movimientos asignados, esperas y carga de trabajo. Las calles compartidas solo refinan alternativas sin deteriorar sustancialmente ese resultado.</p>${roads.pairs.map(p=>`<p><strong>Camionetas ${p.a+1} y ${p.b+1}:</strong> ${p.km.toFixed(2)} km compartidos (${p.outsideKm.toFixed(2)} km fuera de Campana).</p>`).join('')||'<p>No se detectaron tramos compartidos de más de 10 metros.</p>'}<p class="small">Estimación sobre los trazados de Google Maps para las salidas previstas: tolerancia de 8 m y orientación similar, en ambos sentidos. Puede confundir vías paralelas muy cercanas o pasos a distinto nivel. Un tramo utilizado por tres camionetas cuenta en tres parejas. No equivale a kilómetros evitables ni incluye seguimiento GPS; Maps puede cambiar el camino durante la jornada.</p></div>`;}

function operationalWarnings(r){const w=workload(r.routes),warnings=[];for(let i=0;i<r.routes.length;i++){const route=r.routes[i];if(route.wait>=90&&!route.timeline.some(t=>t.wait>=60))warnings.push(`Vehículo ${i+1}: ${Math.round(route.wait)} min de espera acumulada. Revisar la asignación.`);for(const t of route.timeline)if(t.wait>=60)warnings.push(`Vehículo ${i+1}: ${Math.round(t.wait)} min de espera en ${t.stop.address}. Revisar el horario o la asignación; no se demostró que sea inevitable.`);}const mean=w.counts.reduce((a,b)=>a+b,0)/Math.max(1,w.counts.length);if(w.maxLoad>Math.max(300,w.loads.reduce((a,b)=>a+b,0)/Math.max(1,w.loads.length)*1.7))warnings.push(`Carga de trabajo concentrada: una ruta dura ${Math.round(w.maxLoad)} min. Revisar si se puede aliviar sin duplicar zonas. Las cantidades diferentes de movimientos no son por sí solas un problema.`);return warnings;}
function workloadSummary(r){const w=workload(r.routes),warnings=operationalWarnings(r);return `<div class="notice ${warnings.length?'warning':''}"><h2>${warnings.length?'Revisión operativa necesaria':'Carga de trabajo por vehículo'}</h2><p>Espera en ruta: ${Math.round(w.wait)} min en total. Se priorizan zonas coherentes, tiempos y esperas. No se penaliza que los vehículos tengan distintas cantidades de movimientos.</p><div style="overflow-x:auto"><table><thead><tr><th>Vehículo</th><th>Movimientos</th><th>Km</th><th>Disponible en base antes de salir</th><th>Salida</th><th>Fin</th><th>Tiempo en ruta</th><th>Espera</th></tr></thead><tbody>${r.routes.map((route,i)=>`<tr><td>${i+1}</td><td>${w.counts[i]} (${physicalVisits(route)} visitas)</td><td>${route.dist.toFixed(1)}</td><td>${Math.round((route.start??r.config.start)-(route.availableStart??r.config.start))} min</td><td>${clock(route.start??r.config.start)}</td><td>${clock(route.end)}</td><td>${Math.round(w.loads[i])} min</td><td>${Math.round(route.wait)} min</td></tr>`).join('')}</tbody></table></div>${warnings.map(s=>`<p><strong>${esc(s)}</strong></p>`).join('')}<p class="small">Tiempo en ruta incluye conducción, atención, esperas y descanso. La disponibilidad anterior a una salida escalonada se muestra por separado. Los tiempos de viaje siguen siendo estimaciones para la salida inicial de la jornada.</p></div>`;}

async function checkedLocation(address,city,placeId=''){const query=[address,city,'Argentina'].filter(Boolean).join(', ');let matches=await geocode(query,placeId);let valid=matches.filter(c=>!addressMismatch(c,address,city));if(!valid.length&&placeId){matches=await geocode(query);valid=matches.filter(c=>!addressMismatch(c,address,city));}if(!valid.length){const e=new Error(matches.length?addressMismatch(matches[0],address,city):'Google no encontró la dirección completa. Revisá calle, altura y localidad.');e.locationMismatch=true;throw e;}return valid;}

async function runSolver(payload){const worker=new Worker('./solver-worker.mjs?v=33',{type:'module'});return new Promise((resolve,reject)=>{worker.onmessage=e=>{worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data)};worker.onerror=()=>{worker.terminate();reject(Error('No se pudo finalizar el cálculo.'))};worker.postMessage(payload)});}

async function moveManually(id){
 if(busy||!result)return;
 const select=document.querySelector(`[data-move-target="${id}"]`);if(!select)return;const to=Number(select.value),before=result;if(before.routes[to]?.route.some(s=>String(s.id)===String(id)))return status('La parada ya está en esa camioneta.');
 lock(true);document.querySelectorAll('[data-move-stop],[data-move-target],#export').forEach(el=>el.disabled=true);
 try{
  status('Reordenando las camionetas afectadas y verificando horarios…');let updated=await runSolver({action:'move',plan:before,stopId:id,to});if(updated===before){status('La parada ya está en esa camioneta.');return;}
  status('Actualizando recorridos, horarios y mapa…');
  try{updated=await compareRoadPlans(updated,updated.config,updated.departureTime,status)}catch(e){updated.roads={error:e.message};}
  result=updated;destroyFleetMap();renderResults();
  status('Cambio aplicado. Se actualizaron los horarios, kilómetros y enlaces.'+(updated.roads?.error?' No se pudo actualizar el mapa: '+updated.roads.error:''),!!updated.roads?.error);
 }catch(e){status(e.message,true)}finally{lock(false);document.querySelectorAll('[data-move-stop],[data-move-target],#export').forEach(el=>el.disabled=false);}
}

let recalculateAfterStop=false;
function openNewStop(){if(busy)return;recalculateAfterStop=!!result;$('newStopForm').reset();$('newStopService').value=$('service').value;$('newStopError').textContent='';$('newStopNotice').textContent=recalculateAfterStop?'Al guardar se recalcula la hoja completa, incluidos los cambios de distribución manuales. Se actualizan CSV, enlaces y mapa.':'La parada se guarda para esta fecha y se incluirá al calcular.';$('newStop').showModal();}
$('addStop').onclick=openNewStop;$('closeNewStop').onclick=()=>$('newStop').close();
async function changeStops(payload,recalculate){const res=await fetch('/api/manual-stops',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:$('planDate').value,...payload})});const data=await res.json();if(!res.ok)throw Error(data.error);await loadDay();if(!dayReady)throw Error('El cambio se guardó, pero no se pudo actualizar la jornada. Recargá antes de calcular.');if(recalculate)await $('optimize').onclick();}
$('newStopForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const schedule=$('newStopSchedule').value;if(!windows(schedule)){$('newStopError').textContent='Ingresá un horario válido, por ejemplo 9 a 17.';return;}const button=e.target.querySelector('[type=submit]');button.disabled=true;lock(true);try{const stop={type:$('newStopType').value,np:$('newStopNP').value,name:$('newStopName').value,address:$('newStopAddress').value,city:$('newStopCity').value,schedule,service:Number($('newStopService').value)};await changeStops({action:'add',stop},false);$('newStop').close();if(recalculateAfterStop)await $('optimize').onclick();else status('Parada agregada a la jornada.');}catch(err){$('newStopError').textContent=err.message;}finally{button.disabled=false;lock(false);}};
async function removeStop(id){if(busy)return;const stop=stops.find(s=>String(s.id)===String(id));if(!stop)return;const recalculate=!!result;if(stop.type==='Retiro'&&stops.some(s=>s.np===stop.np&&s.type!=='Retiro')){status('Este retiro tiene una entrega vinculada. Quitá primero la entrega si también se cancela; no se puede dejar sin su retiro previo.',true);return;}if(!confirm(`¿Quitar ${stop.np} · ${stop.address||stop.name} de esta jornada? La dirección guardada se conserva.${recalculate?' Se recalcula la hoja completa, incluidos los cambios manuales.':''}`))return;lock(true);try{await changeStops({action:'remove',key:stop.key},recalculate);if(!recalculate)status('Parada quitada de la jornada.');}catch(err){status(err.message,true);}finally{lock(false);}}

async function reorderManually(id){if(busy||!result)return;const select=document.querySelector(`[data-order-target="${id}"]`);if(!select?.value)return status('Elegí antes de qué parada querés ubicarla.',true);const before=result;lock(true);try{status('Verificando el nuevo orden…');let updated=await runSolver({action:'reorder',plan:before,stopId:id,beforeId:select.value});try{updated=await compareRoadPlans(updated,updated.config,updated.departureTime,status);}catch(e){updated.roads={error:e.message};}result=updated;destroyFleetMap();renderResults();status('Orden actualizado. CSV, horarios y enlaces actualizados.'+(updated.roads?.error?' No se pudo actualizar el mapa: '+updated.roads.error:''),!!updated.roads?.error);}catch(e){status(e.message,true);}finally{lock(false);}}
